const fs = require('fs').promises;
const path = require('path');

// Serves the `featured` OrderedCollection (Mastodon pinned posts). The file is
// generated by ActivityPubBuilder.buildFeatured from Data/pinned-posts.json
// and synced into api/data/ by the publish workflow.
module.exports = async function (context, req) {
    try {
        const featuredPath = path.join(__dirname, '../data/featured.json');
        const featuredData = await fs.readFile(featuredPath, 'utf8');
        const parsedFeatured = JSON.parse(featuredData);

        context.res = {
            status: 200,
            headers: {
                'Content-Type': 'application/activity+json',
                'Access-Control-Allow-Origin': '*',
                'Access-Control-Allow-Methods': 'GET, OPTIONS',
                'Access-Control-Allow-Headers': 'Accept, Content-Type',
                'Cache-Control': 'public, max-age=3600'
            },
            body: parsedFeatured
        };
    } catch (error) {
        context.log.error(`Featured error: ${error.message}`);
        context.res = {
            status: 500,
            headers: {
                'Content-Type': 'application/json'
            },
            body: { error: 'Internal server error' }
        };
    }
};
